-- Generated by `drizzle-kit generate`, then HAND-EDITED in two places. Both
-- are deliberate; do not "tidy" them back to drizzle's output. Neither is
-- visible to `drizzle-kit`, so meta/0017_snapshot.json matches
-- lib/db/schema.ts exactly and a future `generate` produces no spurious diff.
--
--   1. `IF NOT EXISTS` on CREATE TABLE / CREATE INDEX. Migrations here are
--      applied BY HAND (`npm run db:migrate`) and nothing in CI applies them
--      (the 2026-09-03 incident behind scripts/check-schema-drift.ts).
--      Re-running a file whose journal entry did not land must be a no-op,
--      not an error.
--   2. The two foreign keys are added inside a `DO` block that checks
--      pg_constraint first: Postgres has no `ADD CONSTRAINT IF NOT EXISTS`,
--      so a bare ALTER would fail on a re-run.
--
-- ROLLBACK: `DROP TABLE IF EXISTS "email_sends";` is lossless for the app
-- ONLY after the code that writes it is reverted first (otherwise every send
-- hits 42P01). Also delete this migration's row from
-- `drizzle.__drizzle_migrations`, or a later re-apply is skipped as already
-- done. Ship order: migration first, then code. Dropping loses only the send
-- log; nothing reads it for correctness except the confirm cap, which then
-- simply starts counting from zero.
CREATE TABLE IF NOT EXISTS "email_sends" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"kind" text NOT NULL,
	"email_hash" text NOT NULL,
	"subscription_id" uuid,
	"target_type" text,
	"target_id" text,
	"run_id" uuid,
	"outcome" text DEFAULT 'attempted' NOT NULL,
	"resend_id" text,
	"error_code" text,
	"completed_at" timestamp with time zone
);
