DO $$ BEGIN
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'email_sends_subscription_id_subscriptions_id_fk' AND conrelid = 'public.email_sends'::regclass) THEN
		ALTER TABLE "email_sends" ADD CONSTRAINT "email_sends_subscription_id_subscriptions_id_fk" FOREIGN KEY ("subscription_id") REFERENCES "public"."subscriptions"("id") ON DELETE set null ON UPDATE no action;
	END IF;
END $$;--> statement-breakpoint
